source4='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    sides = {
        'top': [(0, c) for c in range(w)],
        'bottom': [(h-1, c) for c in range(w)],
        'left': [(r, 0) for r in range(h)],
        'right': [(r, w-1) for r in range(h)],
    }
    edge_counts = {}
    for cells in sides.values():
        i = 0
        while i < len(cells):
            r, c = cells[i]
            color = grid[r][c]
            j = i
            while j + 1 < len(cells) and grid[cells[j+1][0]][cells[j+1][1]] == color:
                j += 1
            if color != bg and j > i:
                edge_counts[color] = edge_counts.get(color, 0) + j - i + 1
            i = j + 1
    edge = max(edge_counts, key=edge_counts.get) if edge_counts else 2
    runs = {}
    for side, cells in sides.items():
        arr = []
        i = 0
        while i < len(cells):
            if grid[cells[i][0]][cells[i][1]] != edge:
                i += 1
                continue
            j = i
            while j + 1 < len(cells) and grid[cells[j+1][0]][cells[j+1][1]] == edge:
                j += 1
            arr.append((i, j))
            i = j + 1
        runs[side] = arr
    opposite = {'top':'bottom', 'bottom':'top', 'left':'right', 'right':'left'}
    points = [(r,c,grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] != bg and grid[r][c] != edge]
    for side in ('top','bottom','left','right'):
        oside = opposite[side]
        for a,b in runs[side]:
            candidates = runs[oside]
            if not candidates:
                continue
            # Corresponding edge bands are the run of matching length, when available.
            other = min(candidates, key=lambda x: (abs((x[1]-x[0])-(b-a)), abs(x[0]-a)))
            oa, ob = other
            for r,c,color in points:
                pos = c if side in ('top','bottom') else r
                if not (a <= pos <= b):
                    continue
                offset = pos-a
                mapped = min(oa+offset, ob)
                out[r][c] = 4
                # Draw from the point back to its own border.
                if side == 'top':
                    cells = ((rr,c) for rr in range(r-1,-1,-1))
                elif side == 'bottom':
                    cells = ((rr,c) for rr in range(r+1,h))
                elif side == 'left':
                    cells = ((r,cc) for cc in range(c-1,-1,-1))
                else:
                    cells = ((r,cc) for cc in range(c+1,w))
                for rr,cc in cells:
                    if grid[rr][cc] == edge:
                        break
                    out[rr][cc] = color
                # Transfer the same offset to the opposite edge band and span the grid.
                if side in ('top','bottom'):
                    col = mapped
                    for rr in range(h):
                        if grid[rr][col] != edge:
                            out[rr][col] = color
                else:
                    row = mapped
                    for cc in range(w):
                        if grid[row][cc] != edge:
                            out[row][cc] = color
    return out
'''
